def transform(grid):
    # Read the marked intersections of the lattice, skipping its outer frame.
    # The unmarked lattice color is 4; ordinary cells are color 7.
    return [
        [grid[r][c] if grid[r][c] not in (4, 7) else 7 for c in (2, 8, 14, 20)]
        for r in (6, 12, 18)
    ]
